    var createExpressMiddleware, config, expressConstStub, expressUseStub, expressRouteStub

    beforeEach(function() {
        var unitUnderTestPath = '../../../lib/commands/createMiddlewareCmd.js'
          , requires = { 'express' : mockExpress() }

